result:
Here's a complete game: **Orb Runner**. Move with the mouse or WASD/arrow keys, collect glowing orbs, and dodge red hazards. Hazards speed up and spawn more often over time. Reach 300 points to win, or lose all 3 lives for game over. Sound effects are generated with WebAudio.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Orb Runner</title>
<style>
  html,body{margin:0;height:100%;background:#05060f;display:flex;align-items:center;justify-content:center;font-family:monospace}
  canvas{background:radial-gradient(circle at 50% 40%,#10163a,#05060f);border:2px solid #2a3470;box-shadow:0 0 30px #2a347088;max-width:100%;max-height:100%;cursor:none}
</style>
</head>
<body>
<canvas id="c" width="800" height="560"></canvas>
<script>
(function(){
const cv=document.getElementById('c'),ctx=cv.getContext('2d');
const W=cv.width,H=cv.height,WIN_SCORE=300;
window.gameState={score:0,state:"menu"};

let state="menu",score=0,lives=3,time=0,player,orbs,hazards,particles,keys={},mouse={x:W/2,y:H/2,active:false},orbTimer,hazTimer,invuln,best=0;

function sync(){window.gameState.score=score;window.gameState.state=state;}

// audio
let ac=null;
function beep(freq,dur,type,vol,slide){
  try{
    if(!ac)ac=new (window.AudioContext||window.webkitAudioContext)();
    if(ac.state==="suspended")ac.resume();
    const o=ac.createOscillator(),g=ac.createGain();
    o.type=type||"sine";o.frequency.setValueAtTime(freq,ac.currentTime);
    if(slide)o.frequency.exponentialRampToValueAtTime(slide,ac.currentTime+dur);
    g.gain.setValueAtTime(vol||0.1,ac.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001,ac.currentTime+dur);
    o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+dur);
  }catch(e){}
}

function reset(){
  score=0;lives=3;time=0;invuln=0;
  player={x:W/2,y:H/2,r:14};
  orbs=[];hazards=[];particles=[];
  orbTimer=0;hazTimer=0;
  spawnOrb();spawnOrb();
  for(let i=0;i<3;i++)spawnHazard();
}
function start(){reset();state="playing";sync();beep(440,0.15,"square",0.08,880);}

function spawnOrb(){
  orbs.push({x:30+Math.random()*(W-60),y:30+Math.random()*(H-60),r:10,life:7,ph:Math.random()*6});
}
function spawnHazard(){
  const diff=1+time/20;
  const sp=(70+Math.random()*50)*Math.min(diff,4);
  let x,y,side=Math.floor(Math.random()*4);
  if(side==0){x=-20;y=Math.random()*H}
  else if(side==1){x=W+20;y=Math.random()*H}
  else if(side==2){x=Math.random()*W;y=-20}
  else{x=Math.random()*W;y=H+20}
  // aim roughly at player
  let a=Math.atan2(player.y-y,player.x-x)+(Math.random()-0.5)*1.0;
  hazards.push({x,y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,r:11+Math.random()*8,rot:0});
}
function burst(x,y,col,n){
  for(let i=0;i<n;i++){
    const a=Math.random()*6.283,s=40+Math.random()*160;
    particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:0.6,col});
  }
}

function update(dt){
  time+=dt;
  // movement
  let sp=280;
  let dx=0,dy=0;
  if(keys.ArrowLeft||keys.a)dx-=1;
  if(keys.ArrowRight||keys.d)dx+=1;
  if(keys.ArrowUp||keys.w)dy-=1;
  if(keys.ArrowDown||keys.s)dy+=1;
  if(dx||dy){
    const l=Math.hypot(dx,dy);
    player.x+=dx/l*sp*dt;player.y+=dy/l*sp*dt;
    mouse.active=false;
  }else if(mouse.active){
    const mx=mouse.x-player.x,my=mouse.y-player.y,d=Math.hypot(mx,my);
    const step=Math.min(d,sp*1.6*dt);
    if(d>1){player.x+=mx/d*step;player.y+=my/d*step;}
  }
  player.x=Math.max(player.r,Math.min(W-player.r,player.x));
  player.y=Math.max(player.r,Math.min(H-player.r,player.y));
  if(invuln>0)invuln-=dt;

  // spawning (gets harder)
  orbTimer+=dt;
  if(orbTimer>1.4&&orbs.length<5){orbTimer=0;spawnOrb();}
  hazTimer+=dt;
  const interval=Math.max(0.35,1.6-time*0.025);
  if(hazTimer>interval){hazTimer=0;spawnHazard();}

  // orbs
  for(let i=orbs.length-1;i>=0;i--){
    const o=orbs[i];o.life-=dt;
    if(o.life<=0){orbs.splice(i,1);continue;}
    if(Math.hypot(o.x-player.x,o.y-player.y)<o.r+player.r){
      orbs.splice(i,1);score+=10;
      burst(o.x,o.y,"#7fffd4",14);
      beep(660+Math.min(score,300)*2,0.12,"sine",0.12,1200);
      if(score>=WIN_SCORE){state="won";best=Math.max(best,score);beep(880,0.5,"triangle",0.15,1760);sync();return;}
      sync();
    }
  }
  // hazards
  for(let i=hazards.length-1;i>=0;i--){
    const h=hazards[i];
    h.x+=h.vx*dt;h.y+=h.vy*dt;h.rot+=dt*3;
    if(h.x<-60||h.x>W+60||h.y<-60||h.y>H+60){hazards.splice(i,1);continue;}
    if(invuln<=0&&Math.hypot(h.x-player.x,h.y-player.y)<h.r*0.85+player.r*0.8){
      lives--;invuln=1.5;
      burst(player.x,player.y,"#ff4060",24);
      beep(180,0.3,"sawtooth",0.15,50);
      hazards.splice(i,1);
      if(lives<=0){state="over";best=Math.max(best,score);sync();return;}
    }
  }
  for(let i=particles.length-1;i>=0;i--){
    const p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;
    if(p.life<=0)particles.splice(i,1);
  }
}

function glowCircle(x,y,r,col,blur){
  ctx.shadowColor=col;ctx.shadowBlur=blur;ctx.fillStyle=col;
  ctx.beginPath();ctx.arc(x,y,r,0,6.283);ctx.fill();
  ctx.shadowBlur=0;
}
function text(t,x,y,size,col,align){
  ctx.font="bold "+size+"px monospace";ctx.fillStyle=col||"#fff";ctx.textAlign=align||"center";ctx.fillText(t,x,y);
}

function draw(){
  ctx.clearRect(0,0,W,H);
  if(state==="menu"){
    ctx.shadowColor="#7fffd4";ctx.shadowBlur=20;
    text("ORB RUNNER",W/2,170,64,"#7fffd4");
    ctx.shadowBlur=0;
    glowCircle(W/2-150,230,10,"#7fffd4",20);
    glowCircle(W/2+150,230,10,"#7fffd4",20);
    text("Collect glowing orbs. Avoid the red spikes.",W/2,260,20,"#cfd8ff");
    text("Move: Mouse  or  WASD / Arrow keys",W/2,310,18,"#9aa8e8");
    text("Orb = +10 points   |   Spike hit = -1 life (3 lives)",W/2,340,18,"#9aa8e8");
    text("Reach "+WIN_SCORE+" points to win. It gets faster over time!",W/2,370,18,"#9aa8e8");
    if(Math.floor(performance.now()/500)%2)text("Press ENTER / SPACE or click to start",W/2,450,24,"#ffd166");
    if(best)text("Best: "+best,W/2,490,18,"#9aa8e8");
    return;
  }
  // orbs
  const t=performance.now()/1000;
  for(const o of orbs){
    const pulse=1+Math.sin(t*5+o.ph)*0.15;
    const fade=o.life<2?(Math.sin(t*20)>0?1:0.3):1;
    ctx.globalAlpha=fade;
    glowCircle(o.x,o.y,o.r*pulse,"#7fffd4",25);
    ctx.fillStyle="#fff";ctx.beginPath();ctx.arc(o.x-2,o.y-2,3,0,6.283);ctx.fill();
    ctx.globalAlpha=1;
  }
  // hazards
  for(const h of hazards){
    ctx.save();ctx.translate(h.x,h.y);ctx.rotate(h.rot);
    ctx.shadowColor="#ff2040";ctx.shadowBlur=14;ctx.fillStyle="#ff3050";
    ctx.beginPath();
    for(let i=0;i<16;i++){
      const a=i/16*6.283,r=i%2?h.r*0.55:h.r*1.1;
      ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);
    }
    ctx.closePath();ctx.fill();ctx.restore();
  }
  ctx.shadowBlur=0;
  // particles
  for(const p of particles){
    ctx.globalAlpha=Math.max(0,p.life/0.6);ctx.fillStyle=p.col;
    ctx.fillRect(p.x-2,p.y-2,4,4);
  }
  ctx.globalAlpha=1;
  // player
  if(state!=="over"){
    if(!(invuln>0&&Math.floor(invuln*10)%2))glowCircle(player.x,player.y,player.r,"#ffd166",22);
  }
  // HUD
  text("Score: "+score,16,32,24,"#fff","left");
  text("Lives: "+"♥".repeat(Math.max(0,lives)),W-16,32,24,"#ff6b88","right");
  text("Level "+(1+Math.floor(time/15)),W/2,32,18,"#9aa8e8");

  if(state==="over"||state==="won"){
    ctx.fillStyle="rgba(5,6,15,0.75)";ctx.fillRect(0,0,W,H);
    if(state==="over"){
      text("GAME OVER",W/2,220,60,"#ff4060");
    }else{
      text("YOU WIN!",W/2,220,60,"#7fffd4");
    }
    text("Score: "+score+"    Best: "+best,W/2,280,26,"#fff");
    text("Press ENTER / SPACE or click to play again",W/2,350,22,"#ffd166");
  }
}

let last=performance.now();
function loop(now){
  const dt=Math.min(0.05,(now-last)/1000);last=now;
  if(state==="playing")update(dt);
  else if(particles&&particles.length)for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;}
  draw();
  requestAnimationFrame(loop);
}

function act(){
  if(state!=="playing")start();
}
window.addEventListener("keydown",e=>{
  const k=e.key.length===1?e.key.toLowerCase():e.key;
  keys[k]=true;
  if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"," "].includes(e.key))e.preventDefault();
  if(e.key==="Enter"||e.key===" ")act();
});
window.addEventListener("keyup",e=>{
  const k=e.key.length===1?e.key.toLowerCase():e.key;
  keys[k]=false;
});
cv.addEventListener("mousemove",e=>{
  const r=cv.getBoundingClientRect();
  mouse.x=(e.clientX-r.left)*W/r.width;
  mouse.y=(e.clientY-r.top)*H/r.height;
  mouse.active=true;
});
cv.addEventListener("mousedown",act);

reset();
sync();
requestAnimationFrame(loop);
})();
</script>
</body>
</html>
```

**Notes**
- `window.gameState` is updated on every score change and state transition (`menu`, `playing`, `over`, `won`).
- Difficulty ramps up as hazards get faster, spawn more frequently, and the level counter increases every 15 seconds.
- After game over or a win, press Enter/Space or click to restart without reloading.
